
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_x3lyp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_x3lyp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.440274635949547e+00, -3.375959731622901e+00, -3.285885929356418e+00, -3.161208421404753e+00, -2.991519409642476e+00, -2.766082505446012e+00, -2.476720957100858e+00, -2.122905669389689e+00, -1.718094796138174e+00, -1.291077480118656e+00, -8.716835360737935e-01, -5.905470416908120e-01, -5.096602966397205e-01, -4.252382481713545e-01, -3.101449768902081e-01, -1.953022045563938e-01, -1.113659222019875e-01, -6.100778109517553e-02, -3.457192182770423e-02, -2.286241622227486e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


